import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast via best-of-many greedy Steiner trees: attach destinations
    one at a time to a growing tree, making already-used edges free so trunk
    costs are paid once and shared across destinations. Try several
    attachment orderings plus per-dst independent shortest paths; keep the
    candidate whose union of used edges is cheapest. A fixpoint refinement
    re-routes each dst over the free trunk (union only shrinks). All
    partitions reuse the same per-dst edge list (no redundant transfers)."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    targets = [d for d in dsts if d != src]

    try:
        dist0, spaths0 = nx.single_source_dijkstra(h, src, weight="cost")
    except Exception:
        dist0, spaths0 = {}, {}

    def build_tree(order):
        w = h.copy()
        paths = {}
        remaining = list(order)
        while remaining:
            try:
                dist, sp = nx.single_source_dijkstra(w, src, weight="cost")
            except Exception:
                dist, sp = {}, {}
            cand = [(dist[d], d) for d in remaining if d in dist]
            if cand:
                d = min(cand)[1]
                p = sp[d]
            else:
                d = remaining[0]
                try:
                    p = nx.shortest_path(G, src, d)
                except Exception:
                    remaining.remove(d)
                    continue
            paths[d] = p
            remaining.remove(d)
            for i in range(len(p) - 1):
                u, v = p[i], p[i + 1]
                if w.has_edge(u, v) and w[u][v].get("cost"):
                    w[u][v]["cost"] = 0
        return paths

    def refine(paths):
        for _ in range(len(paths) + 2):
            union = set()
            for p in paths.values():
                for i in range(len(p) - 1):
                    union.add((p[i], p[i + 1]))
            w = h.copy()
            for u, v in union:
                if w.has_edge(u, v):
                    w[u][v]["cost"] = 0
            try:
                _, sp = nx.single_source_dijkstra(w, src, weight="cost")
            except Exception:
                sp = {}
            changed = False
            for d in list(paths):
                if d in sp and sp[d] != paths[d]:
                    paths[d] = sp[d]
                    changed = True
            if not changed:
                break
        return paths

    def tree_score(paths):
        seen, total = set(), 0.0
        for p in paths.values():
            for i in range(len(p) - 1):
                e = (p[i], p[i + 1])
                if e not in seen:
                    seen.add(e)
                    c = h[e[0]][e[1]].get("cost") if h.has_edge(*e) else None
                    total += c if c is not None else 0.0
        return total

    orders = [list(targets),
              sorted(targets, key=lambda d: dist0.get(d, float("inf"))),
              sorted(targets, key=lambda d: -dist0.get(d, 0.0)),
              list(targets)[::-1]]
    best, best_cost = None, None
    seen_orders = set()
    for order in orders:
        key = tuple(order)
        if key in seen_orders:
            continue
        seen_orders.add(key)
        paths = refine(build_tree(order))
        if not paths:
            continue
        c = tree_score(paths)
        if best is None or c < best_cost:
            best, best_cost = paths, c

    indep = {d: spaths0[d] for d in targets if d in spaths0}
    if indep and (best is None or tree_score(indep) < best_cost):
        best, best_cost = dict(indep), tree_score(indep)

    if best is None:
        best = {}

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    for dst in dsts:
        p = best.get(dst)
        if p is None:
            if dst == src:
                p = [src]
            else:
                try:
                    p = nx.shortest_path(G, src, dst)
                except Exception:
                    continue
        edge_list = [[p[i], p[i + 1], G[p[i]][p[i + 1]]]
                     for i in range(len(p) - 1)]
        for j in range(num_partitions):
            bc_topology.set_dst_partition_paths(dst, j, list(edge_list))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
